1	import React, { useRef, useState, useEffect } from 'react';
2	import axios from 'axios';
3	import Sidebar from '../components/Sidebar';
4	import '../css/Dashboard.css';
5	import '../css/VPatrol.css'; // Reusing the high-tech tracking box and HUD dashboard styles
6	import {
7	  PI_CAMERA_STREAM_URL,
8	  CAMERA_SOURCES,
9	  CAMERA_STATUS_MESSAGES,
10	  isPiCameraReachableCached,
11	  markPiUnavailable,
12	  fetchPiSnapshotBitmap,
13	} from '../constants/piCamera';
14	import { API_BASE_URL } from '../constants/api';
15	import { clampBoxToFrame, faceBoxStyle, smoothBox } from '../constants/faceBox';
16	import { describeRecognitionSubject, RECOGNITION_STATUS } from '../constants/recognition';
17	import {
18	  SCAN_INTERVAL_MS,
19	  TARGET_LOCK_MS,
20	  CAPTURE_MAX_WIDTH,
21	  CAPTURE_JPEG_QUALITY,
22	  TRACK_INTERVAL_MS,
23	  TRACK_MAX_WIDTH,
24	  TRACK_JPEG_QUALITY,
25	  BOX_CLEAR_TIMEOUT_MS,
26	  SERVICE_UNAVAILABLE_MSG,
27	  createScanGate,
28	  startTimer,
29	  logScanTimings,
30	  logTrackingTimings,
31	  logLivenessTelemetry,
32	  nowMs,
33	} from '../constants/scanControl';
34	import {
35	  createHeadTurnChallenge,
36	  CHALLENGE_STATE,
37	  LIVENESS_BASELINE_SAMPLES,
38	} from '../constants/liveness';
39	
40	// Pi snapshot failures must persist this long before the page falls back to
41	// the laptop webcam (time-based so the fast tracking loop cannot trip it on a
42	// single hiccup).
43	const PI_FAIL_FALLBACK_MS = 2500;
44	
45	// Concise operator-facing label for each kiosk state (right-hand status card).
46	const GATE_STATE_LABELS = {
47	  SYSTEM_ACTIVE: 'Awaiting target',
48	  PRESENCE_DETECTED: 'Target detected — move closer',
49	  TARGET_LOCKING: 'Analysing biometric vectors',
50	  LIVENESS_CHECK: 'Head-turn check — turn head slightly and hold',
51	  AUTHORIZING: 'Authorising gate transaction',
52	  SECURE_MATCH: 'Access granted',
53	  UNKNOWN_QUERY: 'Access denied',
54	  HARDWARE_ERR: 'Camera unavailable',
55	};
56	
57	const GateScanner = () => {
58	  const videoRef = useRef(null);
59	  const canvasRef = useRef(null);       // full-recognition capture canvas
60	  const trackCanvasRef = useRef(null);  // small tracking capture canvas (independent of recognition)
61	  const containerRef = useRef(null);    // preview container, for face-box projection
62	
63	  const [scanStatus, setScanStatus] = useState("SYSTEM_ACTIVE");
64	  const [displayMessage, setDisplayMessage] = useState("PLACE FACE IN VIEWPORT");
65	  const [faceBox, setFaceBox] = useState(null);
66	  const [scanProgress, setScanProgress] = useState(0);
67	
68	  // Camera source: Raspberry Pi Gate Camera is primary, laptop webcam is fallback
69	  const [cameraSource, setCameraSource] = useState(CAMERA_SOURCES.PI);
70	  const [cameraStatusMsg, setCameraStatusMsg] = useState("Connecting to Pi Gate Camera...");
71	
72	  // Last gate transaction - safe display fields only (never biometric data):
73	  // { identityLabel, attendanceResult, gateAction }.
74	  const [lastDecision, setLastDecision] = useState(null);
75	  const cameraSourceRef = useRef(CAMERA_SOURCES.PI);
76	  const piFailSinceRef = useRef(0);
77	  // Bumped on camera-source switch and unmount; responses from an older
78	  // session are stale and must be ignored.
79	  const scanSessionRef = useRef(0);
80	
81	  const scanStatusRef = useRef("SYSTEM_ACTIVE");
82	  const lockTimerRef = useRef(null);
83	  const progressIntervalRef = useRef(null);
84	  const lockPendingRef = useRef(false);
85	  const candidateUserRef = useRef(null);
86	
87	  // Two INDEPENDENT in-flight locks: tracking (box/liveness) and full
88	  // recognition (identity) never share a guard.
89	  const trackingInFlightRef = useRef(false);
90	  const recognitionInFlightRef = useRef(createScanGate());
91	
92	  // Live tracking state: smoothed frame-space box, last-seen time, and the
93	  // recent valid head-turn ratios that seed the liveness baseline.
94	  const smoothedBoxRef = useRef(null);
95	  const lastFaceSeenAtRef = useRef(0);
96	  const recentRatiosRef = useRef([]);
97	  const challengeRef = useRef(null);
98	  const finalizingRef = useRef(false);
99	
100	  const token = localStorage.getItem("accessToken");
101	  // All recognition traffic goes through the Node backend - never FastAPI directly.
102	  const ATTENDANCE_SCAN_URL = `${API_BASE_URL}/api/attendance/scan`;
103	  const RECOGNIZE_URL = `${API_BASE_URL}/api/facial-recognition/recognize`;
104	  const TRACK_URL = `${API_BASE_URL}/api/facial-recognition/track`;
105	  const CAMERA_LOCATION = "South Entrance Turnstile";
106	
107	  const changeScanState = (nextState, message) => {
108	    setScanStatus(nextState);
109	    scanStatusRef.current = nextState;
110	    if (message) setDisplayMessage(message);
111	  };
112	
113	  useEffect(() => {
114	    initCameraSource();
115	    const trackInterval = setInterval(() => performTrackingScan(), TRACK_INTERVAL_MS);
116	    const scanInterval = setInterval(() => performRecognitionScan(), SCAN_INTERVAL_MS);
117	
118	    return () => {
119	      scanSessionRef.current += 1; // any in-flight tracking/recognition response is now stale
120	      stopGateCamera();
121	      clearInterval(trackInterval);
122	      clearInterval(scanInterval);
123	      if (lockTimerRef.current) clearTimeout(lockTimerRef.current);
124	      if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
125	    };
126	  }, []);
127	
128	  const applyCameraSource = (source, statusMsg) => {
129	    cameraSourceRef.current = source;
130	    setCameraSource(source);
131	    setCameraStatusMsg(statusMsg);
132	    piFailSinceRef.current = 0;
133	  };
134	
135	  // Wipe every per-source tracking artefact so a stale box from the old
136	  // camera source can never render over the new one.
137	  const clearTrackingState = () => {
138	    smoothedBoxRef.current = null;
139	    lastFaceSeenAtRef.current = 0;
140	    recentRatiosRef.current = [];
141	    setFaceBox(null);
142	  };
143	
144	  // Primary source: Raspberry Pi Gate Camera. Probe the snapshot endpoint on
145	  // load; if unreachable, automatically fall back to the laptop webcam.
146	  const initCameraSource = async () => {
147	    const piReachable = await isPiCameraReachableCached();
148	    if (piReachable) {
149	      stopGateCamera();
150	      applyCameraSource(CAMERA_SOURCES.PI, CAMERA_STATUS_MESSAGES.PI_CONNECTED);
151	      changeScanState("SYSTEM_ACTIVE", "GATE TURNSTILE ONLINE // AWAITING TARGET");
152	    } else {
153	      applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
154	      await startGateCamera();
155	    }
156	  };
157	
158	  // Manual camera source switch (Pi Gate Camera / Laptop Webcam)
159	  const selectCameraSource = async (source) => {
160	    if (source === cameraSourceRef.current) return;
161	    scanSessionRef.current += 1; // invalidate responses captured from the old source
162	    resetTurnstileKiosk();
163	    clearTrackingState();
164	    if (source === CAMERA_SOURCES.PI) {
165	      const piReachable = await isPiCameraReachableCached();
166	      if (piReachable) {
167	        stopGateCamera();
168	        applyCameraSource(CAMERA_SOURCES.PI, CAMERA_STATUS_MESSAGES.PI_CONNECTED);
169	      } else {
170	        applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
171	        await startGateCamera();
172	      }
173	    } else {
174	      applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.WEBCAM_ACTIVE);
175	      await startGateCamera();
176	    }
177	  };
178	
179	  const startGateCamera = async () => {
180	    if (!navigator.mediaDevices?.getUserMedia) {
181	      changeScanState("HARDWARE_ERR", "NO CAMERA DETECTED ON THIS TERMINAL");
182	      return;
183	    }
184	    try {
185	      const stream = await navigator.mediaDevices.getUserMedia({
186	        video: {
187	          width: { ideal: 640 },
188	          height: { ideal: 480 },
189	          frameRate: { ideal: 15, max: 20 },
190	          facingMode: "user"
191	        },
192	        audio: false
193	      });
194	      if (videoRef.current) {
195	        videoRef.current.srcObject = stream;
196	        videoRef.current.onloadedmetadata = () => {
197	          videoRef.current.play().catch(() => changeScanState("HARDWARE_ERR", "CAMERA STREAM PAUSED"));
198	        };
199	      }
200	      changeScanState("SYSTEM_ACTIVE", "GATE TURNSTILE ONLINE // AWAITING TARGET");
201	    } catch (err) {
202	      changeScanState("HARDWARE_ERR", "HARDWARE FAILURE: CAMERA NOT DETECTED");
203	    }
204	  };
205	
206	  const stopGateCamera = () => {
207	    if (videoRef.current?.srcObject) {
208	      videoRef.current.srcObject.getTracks().forEach(track => track.stop());
209	    }
210	  };
211	
212	  const processAttendanceTransaction = async (verifiedUser) => {
213	    const subject = describeRecognitionSubject(verifiedUser);
214	    changeScanState("AUTHORIZING", "AUTHORISING GATE TRANSACTION");
215	    setScanProgress(100);
216	
217	    try {
218	      // Hit the Node.js automatic clock-in/out controller with the
219	      // server-verified unique user ID - never a name.
220	      const res = await axios.post(ATTENDANCE_SCAN_URL, {
221	        userId: verifiedUser.id,
222	        cameraLocation: CAMERA_LOCATION
223	      }, {
224	        headers: { Authorization: `Bearer ${token}` }
225	      });
226	
227	      if (res.status >= 200 && res.status < 300 && res.data && res.data.action) {
228	        changeScanState("SECURE_MATCH", `IDENTITY VERIFIED: ${subject.identityLabel}`);
229	        // Render the exact system response action directly onto the kiosk screen
230	        const actionMessage = res.data.action.replace(/_/g, " ");
231	        setDisplayMessage(`${subject.identityLabel} - ${actionMessage}`);
232	        setLastDecision({
233	          identityLabel: subject.identityLabel,
234	          attendanceResult: `Access granted — ${actionMessage.toLowerCase()} successful`,
235	          gateAction: 'Turnstile unlocked'
236	        });
237	      }
238	    } catch (err) {
239	      // Fail closed: any gate-transaction fault leaves the turnstile locked.
240	      console.error("Attendance Sync Failed:", err);
241	      setDisplayMessage("GATE TRANSACTION ROUTING FAULT");
242	      setLastDecision({
243	        identityLabel: subject.identityLabel,
244	        attendanceResult: 'Gate transaction failed — turnstile remains locked',
245	        gateAction: 'Turnstile remains locked'
246	      });
247	    }
248	
249	    setTimeout(() => { resetTurnstileKiosk(); }, 4000);
250	  };
251	
252	  // Capture one frame from the active camera source onto the given hidden
253	  // canvas and return it as a compressed JPEG data URL. The tracking loop uses
254	  // a small/cheap frame; the recognition loop keeps its existing sizing.
255	  const captureFrom = async (canvas, maxWidth, quality) => {
256	    if (!canvas) return null;
257	    const context = canvas.getContext('2d');
258	
259	    if (cameraSourceRef.current === CAMERA_SOURCES.PI) {
260	      let bitmap;
261	      try {
262	        bitmap = await fetchPiSnapshotBitmap();
263	        piFailSinceRef.current = 0;
264	      } catch {
265	        // Pi snapshot failed mid-session - once failures persist past the
266	        // fallback window, switch to the webcam and cache the failure so the
267	        // Pi isn't re-probed on every cycle.
268	        const now = Date.now();
269	        if (!piFailSinceRef.current) {
270	          piFailSinceRef.current = now;
271	        } else if (now - piFailSinceRef.current >= PI_FAIL_FALLBACK_MS) {
272	          markPiUnavailable();
273	          applyCameraSource(CAMERA_SOURCES.WEBCAM, CAMERA_STATUS_MESSAGES.PI_UNAVAILABLE);
274	          await startGateCamera();
275	        }
276	        return null;
277	      }
278	      const scale = Math.min(1, maxWidth / bitmap.width);
279	      canvas.width = Math.round(bitmap.width * scale);
280	      canvas.height = Math.round(bitmap.height * scale);
281	      context.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
282	      bitmap.close?.();
283	      return canvas.toDataURL('image/jpeg', quality);
284	    }
285	
286	    const video = videoRef.current;
287	    if (!video || video.videoWidth === 0) return null;
288	    const scale = Math.min(1, maxWidth / video.videoWidth);
289	    canvas.width = Math.round(video.videoWidth * scale);
290	    canvas.height = Math.round(video.videoHeight * scale);
291	    context.drawImage(video, 0, 0, canvas.width, canvas.height);
292	    return canvas.toDataURL('image/jpeg', quality);
293	  };
294	
295	  const captureFrameBase64 = () => captureFrom(canvasRef.current, CAPTURE_MAX_WIDTH, CAPTURE_JPEG_QUALITY);
296	
297	  // ------------------------------------------------------------------
298	  // A. TRACKING LOOP — detection-only /track endpoint (no identity data).
299	  // Moves the on-screen box, detects presence and samples head-turn movement
300	  // at ~TRACK_INTERVAL_MS. It can never grant access by itself.
301	  // ------------------------------------------------------------------
302	  const performTrackingScan = async () => {
303	    if (trackingInFlightRef.current) return;
304	    const canvas = trackCanvasRef.current;
305	    if (!canvas) return;
306	    const status = scanStatusRef.current;
307	    if (status === "SECURE_MATCH" || status === "UNKNOWN_QUERY" || status === "AUTHORIZING" || status === "HARDWARE_ERR") return;
308	
309	    trackingInFlightRef.current = true;
310	    const scanSession = scanSessionRef.current;
311	    try {
312	      const captureTimer = startTimer();
313	      const imageBase64 = await captureFrom(canvas, TRACK_MAX_WIDTH, TRACK_JPEG_QUALITY);
314	      const captureMs = captureTimer();
315	      if (!imageBase64) return;
316	
317	      const requestTimer = startTimer();
318	      const res = await axios.post(TRACK_URL, { image: imageBase64 }, {
319	        headers: { Authorization: `Bearer ${token}` }
320	      });
321	      // Stale response: camera source switched (or unmounted) mid-request.
322	      if (scanSession !== scanSessionRef.current) return;
323	      logTrackingTimings({ captureMs, requestMs: requestTimer(), inferenceMs: res.data?.inferenceMs });
324	      handleTrackingResult(res.data, canvas);
325	    } catch {
326	      // Tracking is best-effort; the recognition loop owns service-fault
327	      // messaging and backoff.
328	    } finally {
329	      trackingInFlightRef.current = false;
330	    }
331	  };
332	
333	  const handleTrackingResult = (data, canvas) => {
334	    const { faceDetected, faceCount = 0, box, headTurnRatio } = data || {};
335	    const now = nowMs();
336	
337	    if (faceDetected && Array.isArray(box) && box.length === 4) {
338	      lastFaceSeenAtRef.current = now;
339	      const frame = { width: canvas.width, height: canvas.height };
340	      // Smooth in frame space, then project onto the current container size so
341	      // preview/container resizes are handled on every tracking update.
342	      smoothedBoxRef.current = smoothBox(smoothedBoxRef.current, clampBoxToFrame(box, frame.width, frame.height));
343	      const containerEl = containerRef.current;
344	      const container = containerEl
345	        ? { width: containerEl.clientWidth, height: containerEl.clientHeight }
346	        : frame;
347	      const sb = smoothedBoxRef.current;
348	      setFaceBox(faceBoxStyle([sb.x, sb.y, sb.width, sb.height], frame, container, 'contain'));
349	
350	      const ratio = headTurnRatio ?? null;
351	      if (ratio !== null) {
352	        recentRatiosRef.current = [...recentRatiosRef.current, ratio].slice(-LIVENESS_BASELINE_SAMPLES);
353	      }
354	
355	      if (faceCount > 1) {
356	        // Never continue authorisation with more than one person in frame.
357	        abortAuthorizationForMultipleFaces();
358	        return;
359	      }
360	
361	      const status = scanStatusRef.current;
362	
363	      if (status === "LIVENESS_CHECK") {
364	        const challenge = challengeRef.current;
365	        if (!challenge || !candidateUserRef.current) { resetTurnstileKiosk(); return; }
366	        const result = challenge.observe(ratio, now);
367	        logLivenessTelemetry({ baseline: result.baseline, current: ratio, delta: result.delta, consecutive: result.consecutive });
368	        // Progress comes ONLY from real tracking observations.
369	        setScanProgress(Math.min(96, Math.round((result.consecutive / challenge.requiredConsecutiveSamples) * 96)));
370	        if (result.state === CHALLENGE_STATE.TIMED_OUT) {
371	          failLivenessTimeout();
372	        } else if (result.state === CHALLENGE_STATE.PASSED) {
373	          runFinalConfirmation();
374	        }
375	        return;
376	      }
377	
378	      if (status === "SYSTEM_ACTIVE" || status === "PRESENCE_DETECTED") {
379	        const proximityPct = (sb.width / frame.width) * 100;
380	        if (proximityPct < 8) {
381	          changeScanState("PRESENCE_DETECTED", "TARGET DETECTED // MOVE CLOSER");
382	        } else {
383	          changeScanState("TARGET_LOCKING", "LOCKING BIOMETRIC VECTORS...");
384	        }
385	      }
386	      return;
387	    }
388	
389	    // No face in this tracking sample.
390	    if (scanStatusRef.current === "LIVENESS_CHECK" && challengeRef.current) {
391	      const result = challengeRef.current.observe(null, now);
392	      if (result.state === CHALLENGE_STATE.TIMED_OUT) {
393	        failLivenessTimeout();
394	        return;
395	      }
396	    }
397	    // Retain the box through a brief miss, then clear it and rearm.
398	    if (lastFaceSeenAtRef.current && now - lastFaceSeenAtRef.current >= BOX_CLEAR_TIMEOUT_MS) {
399	      clearTrackingState();
400	      const status = scanStatusRef.current;
401	      if (status === "PRESENCE_DETECTED" || status === "TARGET_LOCKING" || status === "LIVENESS_CHECK") {
402	        // Person left the frame — fail closed and return to standby.
403	        resetTurnstileKiosk();
404	      }
405	    }
406	  };
407	
408	  const abortAuthorizationForMultipleFaces = () => {
409	    if (lockTimerRef.current) clearTimeout(lockTimerRef.current);
410	    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
411	    lockPendingRef.current = false;
412	    candidateUserRef.current = null;
413	    challengeRef.current = null;
414	    setScanProgress(0);
415	    changeScanState("PRESENCE_DETECTED", "MULTIPLE FACES DETECTED — ONE PERSON AT A TIME");
416	  };
417	
418	  // ------------------------------------------------------------------
419	  // B. FULL RECOGNITION LOOP — identity only, ~once per SCAN_INTERVAL_MS,
420	  // and ONLY while identification is needed (TARGET_LOCKING). Once a
421	  // candidate is secured it stops until the final confirmation.
422	  // ------------------------------------------------------------------
423	  const performRecognitionScan = async () => {
424	    const gate = recognitionInFlightRef.current;
425	    // No overlapping requests; short backoff after a recognition-service failure.
426	    if (!gate.canScan()) return;
427	    const canvas = canvasRef.current;
428	    if (!canvas) return;
429	    if (scanStatusRef.current !== "TARGET_LOCKING" || lockPendingRef.current) return;
430	
431	    gate.begin();
432	    const totalTimer = startTimer();
433	    const scanSession = scanSessionRef.current;
434	
435	    try {
436	      const captureTimer = startTimer();
437	      const imageBase64 = await captureFrameBase64();
438	      const captureMs = captureTimer();
439	      if (!imageBase64) return;
440	
441	      const apiTimer = startTimer();
442	      const res = await axios.post(RECOGNIZE_URL, {
443	        image: imageBase64,
444	        cameraLocation: CAMERA_LOCATION
445	      }, {
446	        headers: { Authorization: `Bearer ${token}` }
447	      });
448	      // Stale response: camera source switched (or unmounted) mid-request.
449	      if (scanSession !== scanSessionRef.current) return;
450	      logScanTimings({
451	        captureMs,
452	        apiMs: apiTimer(),
453	        totalMs: totalTimer(),
454	        serverTimings: res.data?.timings
455	      });
456	
457	      if (scanStatusRef.current !== "TARGET_LOCKING" || lockPendingRef.current) return;
458	
459	      const recognizedUser = res.data?.user;
460	      if (!recognizedUser) return; // presence/no-face resets belong to the tracking loop
461	
462	      // TARGET LOCKING SEQUENCE — one decision per lock window.
463	      lockPendingRef.current = true;
464	      setScanProgress(12);
465	      let progress = 12;
466	      progressIntervalRef.current = setInterval(() => {
467	        progress += Math.floor(Math.random() * 14) + 4;
468	        if (progress >= 96) { setScanProgress(96); clearInterval(progressIntervalRef.current); }
469	        else { setScanProgress(progress); }
470	      }, 120);
471	
472	      lockTimerRef.current = setTimeout(() => {
473	        clearInterval(progressIntervalRef.current);
474	        lockPendingRef.current = false;
475	        resolveCandidateDecision(recognizedUser);
476	      }, TARGET_LOCK_MS);
477	    } catch (err) {
478	      // Node/FastAPI unavailable - back off instead of flooding the endpoint.
479	      // The camera preview keeps running; webcam fallback is ONLY for Pi failure.
480	      console.error("Gate AI Link Fault:", err);
481	      gate.applyBackoff();
482	      setDisplayMessage(SERVICE_UNAVAILABLE_MSG);
483	    } finally {
484	      gate.end();
485	    }
486	  };
487	
488	  const resolveCandidateDecision = (recognizedUser) => {
489	    if (scanStatusRef.current !== "TARGET_LOCKING") return;
490	
491	    if (recognizedUser && recognizedUser.status === RECOGNITION_STATUS.AUTHORIZED) {
492	      candidateUserRef.current = recognizedUser;
493	      // Baseline = median of up to three recent valid tracking ratios; the
494	      // challenge then requires sustained CHANGE from that baseline.
495	      challengeRef.current = createHeadTurnChallenge({
496	        initialSamples: recentRatiosRef.current,
497	      });
498	      setScanProgress(0);
499	      changeScanState("LIVENESS_CHECK", "TURN HEAD SLIGHTLY AND HOLD");
500	    } else if (recognizedUser && recognizedUser.status === RECOGNITION_STATUS.SUSPENDED) {
501	      // Server already denied access and wrote the security log.
502	      const subject = describeRecognitionSubject(recognizedUser);
503	      changeScanState("UNKNOWN_QUERY", `${subject.identityLabel} - ${subject.accessLabel}`);
504	      setLastDecision({
505	        identityLabel: subject.identityLabel,
506	        attendanceResult: 'Access denied — account suspended',
507	        gateAction: 'Turnstile remains locked'
508	      });
509	      setScanProgress(0);
510	      setTimeout(() => { resetTurnstileKiosk(); }, 3500);
511	    } else {
512	      // Unknown person - server already wrote the intrusion log.
513	      changeScanState("UNKNOWN_QUERY", "PERIMETER BREACH: ACCESS DENIED");
514	      setLastDecision({
515	        identityLabel: describeRecognitionSubject(recognizedUser).identityLabel,
516	        attendanceResult: 'Access denied — unknown person',
517	        gateAction: 'Turnstile remains locked'
518	      });
519	      setScanProgress(0);
520	      setTimeout(() => { resetTurnstileKiosk(); }, 3500);
521	    }
522	  };
523	
524	  // Liveness timeout: fail closed — the turnstile stays locked and no
525	  // Attendance record is ever created from an unconfirmed challenge.
526	  const failLivenessTimeout = () => {
527	    const subject = describeRecognitionSubject(candidateUserRef.current);
528	    candidateUserRef.current = null;
529	    challengeRef.current = null;
530	    setScanProgress(0);
531	    changeScanState("UNKNOWN_QUERY", "LIVENESS TIMEOUT — ACCESS DENIED");
532	    setLastDecision({
533	      identityLabel: subject.identityLabel,
534	      attendanceResult: 'Access denied — head-turn not confirmed in time',
535	      gateAction: 'Turnstile remains locked'
536	    });
537	    setTimeout(() => { resetTurnstileKiosk(); }, 3500);
538	  };
539	
540	  // ------------------------------------------------------------------
541	  // FINAL SAME-IDENTITY CONFIRMATION — the lightweight tracker never grants
542	  // access. After the head-turn passes, one final full recognition must match
543	  // the ORIGINAL candidate user ID (and still be AUTHORIZED) before the gate
544	  // attendance transaction runs. Anything else fails closed.
545	  // ------------------------------------------------------------------
546	  const runFinalConfirmation = async () => {
547	    const candidate = candidateUserRef.current;
548	    if (!candidate || finalizingRef.current) return;
549	    finalizingRef.current = true;
550	    challengeRef.current = null;
551	    changeScanState("AUTHORIZING", "CONFIRMING IDENTITY BEFORE UNLOCK");
552	    const scanSession = scanSessionRef.current;
553	
554	    try {
555	      const imageBase64 = await captureFrameBase64();
556	      if (!imageBase64) { failFinalConfirmation(); return; }
557	      const res = await axios.post(RECOGNIZE_URL, {
558	        image: imageBase64,
559	        cameraLocation: CAMERA_LOCATION
560	      }, {
561	        headers: { Authorization: `Bearer ${token}` }
562	      });
563	      if (scanSession !== scanSessionRef.current) return;
564	
565	      const finalUser = res.data?.user;
566	      if (
567	        finalUser &&
568	        finalUser.id != null &&
569	        finalUser.id === candidate.id &&
570	        finalUser.status === RECOGNITION_STATUS.AUTHORIZED
571	      ) {
572	        await processAttendanceTransaction(candidate);
573	      } else {
574	        // Identity differs, disappeared, unknown or suspended — fail closed.
575	        failFinalConfirmation();
576	      }
577	    } catch (err) {
578	      console.error("Final identity confirmation failed:", err);
579	      failFinalConfirmation();
580	    } finally {
581	      finalizingRef.current = false;
582	    }
583	  };
584	
585	  const failFinalConfirmation = () => {
586	    candidateUserRef.current = null;
587	    challengeRef.current = null;
588	    setScanProgress(0);
589	    changeScanState("UNKNOWN_QUERY", "IDENTITY NOT CONFIRMED — ACCESS DENIED");
590	    setLastDecision({
591	      identityLabel: 'Unknown Person',
592	      attendanceResult: 'Access denied — final identity confirmation failed',
593	      gateAction: 'Turnstile remains locked'
594	    });
595	    setTimeout(() => { resetTurnstileKiosk(); }, 3500);
596	  };
597	
598	  const resetTurnstileKiosk = () => {
599	    if (lockTimerRef.current) clearTimeout(lockTimerRef.current);
600	    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
601	    lockPendingRef.current = false;
602	    setFaceBox(null);
603	    smoothedBoxRef.current = null;
604	    setScanProgress(0);
605	    candidateUserRef.current = null;
606	    challengeRef.current = null;
607	    changeScanState("SYSTEM_ACTIVE", "GATE TURNSTILE ONLINE // AWAITING TARGET");
608	  };
609	
610	  return (
611	    <div className="dashboard-layout">
612	      <Sidebar />
613	      <main className="dashboard-main gate-main">
614	        <header className="dashboard-header">
615	          <div className="header-titles">
616	            <h1>Perimeter Gate Attendance Terminal</h1>
617	            <p>Main Facility Entrance Turnstile Facial Recognition Interface</p>
618	          </div>
619	        </header>
620	
621	        <div className="camera-source-bar" style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap', marginBottom: '12px' }}>
622	          <span style={{ color: '#94a3b8', fontSize: '0.85rem', fontWeight: 600 }}>Camera Source:</span>
623	          <button
624	            onClick={() => selectCameraSource(CAMERA_SOURCES.PI)}
625	            style={{
626	              padding: '6px 14px', borderRadius: 8, cursor: 'pointer', fontSize: '0.85rem',
627	              border: cameraSource === CAMERA_SOURCES.PI ? '1px solid #3b82f6' : '1px solid #334155',
628	              background: cameraSource === CAMERA_SOURCES.PI ? '#1d4ed8' : '#1e293b', color: '#e2e8f0'
629	            }}
630	          >
631	            Raspberry Pi Gate Camera
632	          </button>
633	          <button
634	            onClick={() => selectCameraSource(CAMERA_SOURCES.WEBCAM)}
635	            style={{
636	              padding: '6px 14px', borderRadius: 8, cursor: 'pointer', fontSize: '0.85rem',
637	              border: cameraSource === CAMERA_SOURCES.WEBCAM ? '1px solid #3b82f6' : '1px solid #334155',
638	              background: cameraSource === CAMERA_SOURCES.WEBCAM ? '#1d4ed8' : '#1e293b', color: '#e2e8f0'
639	            }}
640	          >
641	            Laptop Webcam
642	          </button>
643	          <span style={{ color: '#38bdf8', fontSize: '0.82rem' }}>{cameraStatusMsg}</span>
644	        </div>
645	
646	        <div className="vpatrol-grid gate-grid">
