686	                      {scanStatus === "TARGET_LOCKING" && `ANALYZING: ${scanProgress}%`}
687	                      {scanStatus === "LIVENESS_CHECK" && "MOTION LIVENESS ACTIVE"}
688	                      {scanStatus === "SECURE_MATCH" && "ACCESS GRANTED"}
689	                      {scanStatus === "UNKNOWN_QUERY" && "PERIMETER ALERT"}
690	                    </span>
691	                    <span className="person-name-label">{displayMessage}</span>
692	                  </div>
693	                </div>
694	              )}
695	
696	              <div className="hud-overlay">
697	                <div className="hud-top">
698	                  <div className="hud-left-meta">
699	                    <span className="hud-node">PORTAL_NODE // SOUTH_ENTRANCE_TURNSTILE</span>
