709	                  <p className="hud-engine-log" style={{ color: '#3b82f6' }}>TERMINAL STATE: {displayMessage}</p>
710	                </div>
711	              </div>
712	
713	            </div>
714	          </div>
715	
716	          {/* Compact gate status / transaction result card (right of the camera) */}
717	          <div className="vpatrol-card gate-status-card" role="status" aria-label="Gate status">
718	            <div className="section-header">
719	              <h2>Gate Status</h2>
720	            </div>
721	            <dl className="gate-status-list">
722	              <div className="gate-status-row">
723	                <dt>Current State</dt>
724	                <dd className={`gate-state-value state-${scanStatus.toLowerCase()}`}>
725	                  {GATE_STATE_LABELS[scanStatus] || 'Awaiting target'}
