403	  const handleTrackingResult = (data, canvas) => {
404	    const { faceDetected, faceCount = 0, box, headTurnRatio } = data || {};
405	    const now = nowMs();
406	
407	    if (faceDetected && Array.isArray(box) && box.length === 4) {
408	      lastFaceSeenAtRef.current = now;
409	      const frame = { width: canvas.width, height: canvas.height };
410	      // Smooth in frame space, then project onto the current container size so
411	      // preview/container resizes are handled on every tracking update.
412	      smoothedBoxRef.current = smoothBox(smoothedBoxRef.current, clampBoxToFrame(box, frame.width, frame.height));
413	      const containerEl = containerRef.current;
414	      const container = containerEl
415	        ? { width: containerEl.clientWidth, height: containerEl.clientHeight }
416	        : frame;
417	      const sb = smoothedBoxRef.current;
418	      setFaceBox(faceBoxStyle([sb.x, sb.y, sb.width, sb.height], frame, container, 'contain'));
