425	      if (faceCount > 1) {
426	        const episode = multiFaceRef.current;
427	        if (!episode.since) {
428	          multiFaceRef.current = { since: now, abortedAuth: false, logged: false };
429	        }
430	        // Was an authorisation attempt in progress when this crowd appeared?
431	        // Only an aborted attempt is a security event, not idle passers-by.
432	        if (scanStatusRef.current === "TARGET_LOCKING" ||
433	            scanStatusRef.current === "LIVENESS_CHECK" ||
434	            lockPendingRef.current ||
435	            candidateUserRef.current) {
436	          multiFaceRef.current.abortedAuth = true;
437	        }
438	        // Never continue authorisation with more than one person in frame.
439	        abortAuthorizationForMultipleFaces();
440	        // Persisted long enough + aborted an attempt -> ONE denied audit event
441	        // per episode (never one per 250 ms tracking sample).
442	        if (multiFaceRef.current.abortedAuth &&
443	            !multiFaceRef.current.logged &&
444	            now - multiFaceRef.current.since >= MULTI_FACE_LOG_PERSIST_MS) {
445	          multiFaceRef.current.logged = true;
