447	        }
448	        return;
449	      }
450	      setMultipleFacesNotice(false);
451	      if (multiFaceRef.current.since) {
452	        // Crowd cleared - close the episode so a later one can log again.
453	        multiFaceRef.current = { since: 0, abortedAuth: false, logged: false };
454	        deniedReportedRef.current.delete("MULTIPLE_FACES");
455	      }
456	
457	      const status = scanStatusRef.current;
458	
459	      if (status === "LIVENESS_CHECK") {
460	        const challenge = challengeRef.current;
461	        if (!challenge || !candidateUserRef.current) { resetScanner(); return; }
462	        const result = challenge.observe(ratio, now);
463	        logLivenessTelemetry({ baseline: result.baseline, current: ratio, delta: result.delta, consecutive: result.consecutive });
464	        // Progress comes ONLY from real tracking observations.
465	        setScanProgress(Math.min(96, Math.round((result.consecutive / challenge.requiredConsecutiveSamples) * 96)));
466	        if (result.state === CHALLENGE_STATE.TIMED_OUT) {
467	          failLivenessTimeout();
468	        } else if (result.state === CHALLENGE_STATE.PASSED) {
469	          runFinalConfirmation();
470	        }
471	        return;
472	      }
473	
474	      if (status === "SYSTEM_ACTIVE" || status === "PRESENCE_DETECTED") {
475	        const proximityPct = (sb.width / frame.width) * 100;
476	        if (proximityPct < 5) {
477	          changeScanState("PRESENCE_DETECTED");
478	          setScanProgress(0);
479	        } else {
480	          changeScanState("TARGET_LOCKING");
481	        }
482	      }
483	      return;
484	    }
485	
486	    // No face in this tracking sample.
487	    if (scanStatusRef.current === "LIVENESS_CHECK" && challengeRef.current) {
488	      const result = challengeRef.current.observe(null, now);
489	      if (result.state === CHALLENGE_STATE.TIMED_OUT) {
490	        failLivenessTimeout();
491	        return;
492	      }
493	    }
494	    // Retain the box through a brief miss, then clear it and rearm.
495	    if (lastFaceSeenAtRef.current && now - lastFaceSeenAtRef.current >= BOX_CLEAR_TIMEOUT_MS) {
496	      clearTrackingState();
497	      const status = scanStatusRef.current;
498	      if (status === "PRESENCE_DETECTED" || status === "TARGET_LOCKING" || status === "LIVENESS_CHECK") {
499	        // Person left the frame — fail closed and return to monitoring.
500	        resetScanner();
501	      }
502	    }
503	  };
504	
505	  const abortAuthorizationForMultipleFaces = () => {
506	    if (lockTimerRef.current) clearTimeout(lockTimerRef.current);
507	    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
508	    lockPendingRef.current = false;
509	    candidateUserRef.current = null;
510	    challengeRef.current = null;
511	    setScanProgress(0);
512	    setMultipleFacesNotice(true);
513	    changeScanState("PRESENCE_DETECTED");
514	  };
515	
516	  // ------------------------------------------------------------------
517	  // B. FULL RECOGNITION LOOP — identity only, ~once per SCAN_INTERVAL_MS,
518	  // and ONLY while identification is needed (TARGET_LOCKING). Once a
519	  // candidate is secured it stops until the final confirmation.
520	  // ------------------------------------------------------------------
521	  const performRecognitionScan = async () => {
522	    const gate = recognitionInFlightRef.current;
523	    // No overlapping requests; short backoff after a recognition-service failure.
524	    if (!gate.canScan()) return;
525	    const canvas = canvasRef.current;
526	    if (!canvas) return;
527	    if (scanStatusRef.current !== "TARGET_LOCKING" || lockPendingRef.current) return;
528	
529	    gate.begin();
530	    const totalTimer = startTimer();
531	    const scanSession = scanSessionRef.current;
532	
533	    try {
534	      const captureTimer = startTimer();
535	      const imageBase64 = await captureFrameBase64();
536	      const captureMs = captureTimer();
537	      if (!imageBase64) return;
538	
539	      const apiTimer = startTimer();
540	      const res = await axios.post(RECOGNIZE_URL,
541	        { image: imageBase64, cameraLocation: CAMERA_LOCATION },
542	        { headers: { Authorization: `Bearer ${token}` } }
543	      );
544	      // Stale response: camera source switched (or unmounted) mid-request.
545	      if (scanSession !== scanSessionRef.current) return;
546	      logScanTimings({
547	        captureMs,
548	        apiMs: apiTimer(),
549	        totalMs: totalTimer(),
550	        serverTimings: res.data?.timings
551	      });
552	      setServiceNotice('');
553	
554	      if (scanStatusRef.current !== "TARGET_LOCKING" || lockPendingRef.current) return;
555	
556	      const recognizedUser = res.data?.user;
557	      if (!recognizedUser) return; // presence/no-face resets belong to the tracking loop
558	
559	      // TARGET LOCKING SEQUENCE — one decision per lock window.
560	      lockPendingRef.current = true;
561	      setScanProgress(12);
562	      let progress = 12;
563	      progressIntervalRef.current = setInterval(() => {
564	        progress += Math.floor(Math.random() * 14) + 4;
565	        if (progress >= 96) {
566	          setScanProgress(96);
567	          clearInterval(progressIntervalRef.current);
568	        } else {
569	          setScanProgress(progress);
570	        }
571	      }, 120);
572	
573	      lockTimerRef.current = setTimeout(() => {
574	        clearInterval(progressIntervalRef.current);
575	        lockPendingRef.current = false;
576	        resolveCandidateDecision(recognizedUser);
577	      }, TARGET_LOCK_MS);
578	    } catch (err) {
579	      // Node/FastAPI unavailable - back off instead of flooding the endpoint.
580	      // The camera preview keeps running; webcam fallback is ONLY for Pi failure.
581	      console.error("AI Command Loop Fault:", err);
582	      recognitionInFlightRef.current.applyBackoff();
583	      setServiceNotice(SERVICE_UNAVAILABLE_MSG);
584	    } finally {
585	      recognitionInFlightRef.current.end();
586	    }
587	  };
588	
589	  const resolveCandidateDecision = (recognizedUser) => {
590	    if (scanStatusRef.current !== "TARGET_LOCKING") return;
591	
592	    const currentTimestamp = nowMs();
593	    const logTimeStr = new Date(currentTimestamp).toLocaleTimeString('en-SG', { hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: true });
594	
595	    if (recognizedUser && recognizedUser.status === RECOGNITION_STATUS.AUTHORIZED) {
596	      candidateUserRef.current = recognizedUser;
597	      // Baseline = median of up to three recent valid tracking ratios; the
598	      // challenge then requires sustained CHANGE from that baseline.
599	      challengeRef.current = createHeadTurnChallenge({
600	        initialSamples: recentRatiosRef.current,
601	      });
602	      setScanProgress(0);
603	      changeScanState("LIVENESS_CHECK");
604	    } else {
605	      // Suspended or unknown - the Node backend has already written the
606	      // deduplicated SecurityLog; the client only updates its local timeline.
607	      const isSuspended = recognizedUser && recognizedUser.status === RECOGNITION_STATUS.SUSPENDED;
608	      const subject = describeRecognitionSubject(recognizedUser);
609	
610	      playFeedback('denied');
611	      changeScanState("UNKNOWN_QUERY");
612	      setIdentifiedUser(isSuspended ? `${subject.identityLabel} - SUSPENDED` : "UNKNOWN PERSONNEL");
613	      setScanProgress(0);
614	
615	      const dedupName = isSuspended ? recognizedUser.name : "UNKNOWN";
616	      if (lastLogRef.current.name !== dedupName || (currentTimestamp - lastLogRef.current.timestamp > 10000)) {
617	        const newLog = {
618	          id: `SEC-${currentTimestamp}`,
619	          // New event happening right now - stamped at detection time.
620	          occurredAt: new Date(currentTimestamp).toISOString(),
621	          time: logTimeStr,
622	          type: isSuspended ? 'Suspended Access Attempt' : 'Intrusion Alert',
623	          desc: isSuspended
624	            ? `Suspended account denied at gantry: ${subject.identityLabel}.`
625	            : 'Unregistered personnel detected at gantry.',
626	          severity: 'critical',
627	          icon: isSuspended ? 'DENIED' : 'ALERT',
628	          personnelName: isSuspended ? recognizedUser.name : null,
629	          role: isSuspended ? recognizedUser.role : null,
630	          confidence: recognizedUser ? recognizedUser.confidence : null,
631	          cameraLocation: CAMERA_LOCATION
632	        };
633	
634	        setIncidentLogs(prev => [newLog, ...prev.slice(0, 14)]);
635	        lastLogRef.current = { name: dedupName, timestamp: currentTimestamp };
636	      }
637	
638	      setTimeout(() => { resetScanner(); }, 3500);
639	    }
640	  };
641	
642	  // ------------------------------------------------------------------
643	  // DENIED-OUTCOME AUDIT — posts the FINAL denied outcome (identity mismatch,
644	  // liveness timeout, persistent multi-face abort) to the server-owned
645	  // /denied-event endpoint, then prepends the REAL database record into the
646	  // timeline. Strictly non-fatal: the red fail-closed UI never waits on it,
647	  // and it can never grant access. Unknown/suspended recognition outcomes are
648	  // NOT sent here — /recognize already writes those logs itself.
649	  // ------------------------------------------------------------------
650	  const recordDeniedSecurityEvent = async (reason, candidate = null, confidence = null) => {
651	    if (deniedReportedRef.current.has(reason)) return; // once per scanner cycle
652	    deniedReportedRef.current.add(reason);
653	    const scanSession = scanSessionRef.current;
654	    try {
655	      const res = await axios.post(DENIED_EVENT_URL, {
656	        reason,
657	        candidateUserId: candidate?.id ?? null,
658	        cameraLocation: CAMERA_LOCATION,
659	        confidence: typeof confidence === 'number' ? confidence : null
660	      }, { headers: { Authorization: `Bearer ${token}` } });
661	      // Stale response: camera source switched (or unmounted) mid-request.
662	      if (scanSession !== scanSessionRef.current) return;
663	      const log = res.data?.logged ? res.data.log : null; // deduplicated -> nothing to add
664	      if (log?.id) {
665	        // Prepend the server-created record exactly once per database ID.
666	        setIncidentLogs(prev => prev.some(existing => existing.id === log.id)
667	          ? prev
668	          : [log, ...prev.slice(0, 14)]);
669	      }
670	    } catch (err) {
671	      // Audit sync is best-effort; the denied UI outcome already stands.
672	      console.log("Denied-event sync failed", err);
673	    }
674	  };
675	
676	  // Liveness timeout: fail closed — no access event is ever recorded from an
677	  // unconfirmed challenge.
678	  const failLivenessTimeout = () => {
679	    const candidate = candidateUserRef.current;
680	    recordDeniedSecurityEvent("LIVENESS_TIMEOUT", candidate, candidate?.confidence ?? null);
681	    candidateUserRef.current = null;
682	    challengeRef.current = null;
683	    setScanProgress(0);
684	    playFeedback('denied');
685	    changeScanState("UNKNOWN_QUERY");
686	    setIdentifiedUser("LIVENESS TIMEOUT — NOT CONFIRMED");
687	    setTimeout(() => { resetScanner(); }, 3500);
688	  };
689	
690	  // ------------------------------------------------------------------
691	  // FINAL SAME-IDENTITY CONFIRMATION — the lightweight tracker never grants
692	  // access. After the head-turn passes, one final full recognition must match
693	  // the ORIGINAL candidate user ID (and still be AUTHORIZED) before the
694	  // access event is recorded. Anything else fails closed.
695	  // ------------------------------------------------------------------
696	  const runFinalConfirmation = async () => {
697	    const candidate = candidateUserRef.current;
698	    if (!candidate || finalizingRef.current) return;
699	    finalizingRef.current = true;
700	    challengeRef.current = null;
701	    changeScanState("AUTHORIZING");
702	    const scanSession = scanSessionRef.current;
703	
704	    try {
705	      const imageBase64 = await captureFrameBase64();
706	      if (!imageBase64) { failFinalConfirmation(); return; }
707	      const res = await axios.post(RECOGNIZE_URL,
708	        { image: imageBase64, cameraLocation: CAMERA_LOCATION },
709	        { headers: { Authorization: `Bearer ${token}` } }
710	      );
711	      if (scanSession !== scanSessionRef.current) return;
712	
713	      const finalUser = res.data?.user;
714	      if (
715	        finalUser &&
716	        finalUser.id != null &&
717	        finalUser.id === candidate.id &&
718	        finalUser.status === RECOGNITION_STATUS.AUTHORIZED
719	      ) {
720	        grantFinalAccess(candidate);
721	      } else {
722	        // Identity differs, disappeared, unknown or suspended — fail closed.
723	        failFinalConfirmation();
724	      }
725	    } catch (err) {
726	      console.error("Final identity confirmation failed:", err);
727	      failFinalConfirmation();
728	    } finally {
729	      finalizingRef.current = false;
730	    }
731	  };
732	
733	  const failFinalConfirmation = () => {
734	    // Retain the original candidate's id/confidence for the audit BEFORE the
735	    // fail-closed reset clears them.
736	    const candidate = candidateUserRef.current;
737	    recordDeniedSecurityEvent("FINAL_IDENTITY_MISMATCH", candidate, candidate?.confidence ?? null);
738	    candidateUserRef.current = null;
739	    challengeRef.current = null;
740	    setScanProgress(0);
741	    playFeedback('denied');
742	    changeScanState("UNKNOWN_QUERY");
743	    setIdentifiedUser("IDENTITY NOT CONFIRMED");
744	    setTimeout(() => { resetScanner(); }, 3500);
745	  };
746	
747	  // Frontend filtering of the loaded timeline records (PoC).
748	  const activeFilters = { dateRange: dateFilter, eventType: eventFilter, search: searchFilter };
749	  const filteredLogs = filterSecurityLogs(incidentLogs, activeFilters);
750	
751	  const resetScanner = () => {
752	    if (lockTimerRef.current) clearTimeout(lockTimerRef.current);
753	    if (progressIntervalRef.current) clearInterval(progressIntervalRef.current);
754	    lockPendingRef.current = false;
755	    setIdentifiedUser(null);
756	    setFaceBox(null);
757	    smoothedBoxRef.current = null;
758	    setScanProgress(0);
759	    setMultipleFacesNotice(false);
760	    candidateUserRef.current = null;
761	    challengeRef.current = null;
762	    deniedReportedRef.current.clear(); // new scanner cycle -> denied audit re-armed
763	    changeScanState("SYSTEM_ACTIVE");
764	  };
765	
766	  return (
767	    <div className="dashboard-layout">
768	      <Sidebar />
769	      <main className="dashboard-main vpatrol-main">
770	        <header className="dashboard-header">
771	          <div className="header-titles">
772	            <h1>V-Patrol AI Command Center</h1>
773	            <p>Real-time biometric gantry and anomaly detection timeline</p>
774	          </div>
775	        </header>
776	
777	        <div className="camera-source-bar" style={{ display: 'flex', alignItems: 'center', gap: '12px', flexWrap: 'wrap', marginBottom: '12px' }}>
778	          <span style={{ color: '#94a3b8', fontSize: '0.85rem', fontWeight: 600 }}>Camera Source:</span>
779	          <button
780	            onClick={() => selectCameraSource(CAMERA_SOURCES.PI)}
781	            style={{
782	              padding: '6px 14px', borderRadius: 8, cursor: 'pointer', fontSize: '0.85rem',
783	              border: cameraSource === CAMERA_SOURCES.PI ? '1px solid #3b82f6' : '1px solid #334155',
784	              background: cameraSource === CAMERA_SOURCES.PI ? '#1d4ed8' : '#1e293b', color: '#e2e8f0'
785	            }}
786	          >
787	            Raspberry Pi Gate Camera
788	          </button>
789	          <button
790	            onClick={() => selectCameraSource(CAMERA_SOURCES.WEBCAM)}
791	            style={{
792	              padding: '6px 14px', borderRadius: 8, cursor: 'pointer', fontSize: '0.85rem',
793	              border: cameraSource === CAMERA_SOURCES.WEBCAM ? '1px solid #3b82f6' : '1px solid #334155',
794	              background: cameraSource === CAMERA_SOURCES.WEBCAM ? '#1d4ed8' : '#1e293b', color: '#e2e8f0'
795	            }}
796	          >
797	            Laptop Webcam
798	          </button>
799	          <span style={{ color: '#38bdf8', fontSize: '0.82rem' }}>{cameraStatusMsg}</span>
800	          {serviceNotice && (
801	            <span style={{ color: '#f59e0b', fontSize: '0.82rem', fontWeight: 600 }}>{serviceNotice}</span>
802	          )}
803	        </div>
804	
805	        <div className="vpatrol-grid">
806	          <div className="vpatrol-card monitor-section">
807	            <div ref={containerRef} className={`cctv-container state-theme-${scanStatus.toLowerCase()}`} style={{ width: '100%', height: '100%' }}>
808	              {cameraSource === CAMERA_SOURCES.PI && (
809	                <img
810	                  src={PI_CAMERA_STREAM_URL}
811	                  alt="Raspberry Pi gate camera live preview"
812	                  className="video-feed"
813	                />
814	              )}
815	              <video
816	                ref={videoRef}
817	                autoPlay
818	                playsInline
819	                muted
820	                className="video-feed"
821	                style={cameraSource === CAMERA_SOURCES.PI ? { display: 'none' } : undefined}
822	              />
823	              <canvas ref={canvasRef} style={{ display: 'none' }} />
824	              <canvas ref={trackCanvasRef} style={{ display: 'none' }} />
825	
826	              {scanStatus === "HARDWARE_ERR" && (
827	                <div className="camera-error-overlay" style={{
828	                  position: 'absolute', inset: 0, display: 'flex', flexDirection: 'column',
829	                  alignItems: 'center', justifyContent: 'center', textAlign: 'center',
830	                  background: 'rgba(15,23,42,0.92)', color: '#e2e8f0', padding: '24px', zIndex: 5
831	                }}>
832	                  <SafeMuiIcon icon={VideocamOffIcon} style={{ fontSize: 40 }} aria-hidden="true" />
833	                  <h3 style={{ margin: '10px 0 4px' }}>Camera unavailable</h3>
834	                  <p style={{ color: '#94a3b8', maxWidth: 360 }}>
835	                    Allow camera access in your browser, close other apps using the webcam, then
836	                    reload. If this device has no camera, the live patrol feed can't run here.
837	                  </p>
838	                  <button
839	                    onClick={startCCTV}
840	                    style={{ marginTop: 12, padding: '8px 16px', borderRadius: 8, border: '1px solid #334155', background: '#1e293b', color: '#e2e8f0', cursor: 'pointer' }}
841	                  >
842	                    Retry camera
843	                  </button>
844	                </div>
845	              )}
846	
847	              {faceBox && (
848	                <div
849	                  className={`face-tracking-box state-${scanStatus.toLowerCase()}`}
850	                  style={{
851	                    top: faceBox.top,
852	                    left: faceBox.left,
853	                    width: faceBox.width,
854	                    height: faceBox.height,
855	                    transition: 'top 100ms linear, left 100ms linear, width 100ms linear, height 100ms linear'
856	                  }}
857	                >
858	                  <div className="corner-bracket top-left"></div>
859	                  <div className="corner-bracket top-right"></div>
860	                  <div className="corner-bracket bottom-left"></div>
861	                  <div className="corner-bracket bottom-right"></div>
862	
863	                  {scanStatus === "TARGET_LOCKING" && <div className="matrix-scan-line"></div>}
864	
865	                  <div className="box-identity-panel">
866	                    <span className="access-status-label">
867	                      {scanStatus === "TARGET_LOCKING" && `ANALYZING: ${scanProgress}%`}
868	                      {scanStatus === "LIVENESS_CHECK" && "MOTION LIVENESS ACTIVE"}
869	                      {scanStatus === "AUTHORIZING" && "CONFIRMING IDENTITY"}
870	                      {scanStatus === "SECURE_MATCH" && "GRANT ACCESS"}
871	                      {scanStatus === "UNKNOWN_QUERY" && "ACCESS DENIED"}
872	                    </span>
873	                    <span className="person-name-label">
874	                      {multipleFacesNotice && "MULTIPLE FACES DETECTED — ONE PERSON AT A TIME"}
875	                      {!multipleFacesNotice && scanStatus === "TARGET_LOCKING" && "LOCKING VECTORS..."}
876	                      {!multipleFacesNotice && scanStatus === "LIVENESS_CHECK" && "TURN HEAD SLIGHTLY AND HOLD"}
877	                      {!multipleFacesNotice && scanStatus === "AUTHORIZING" && "HOLD STILL"}
878	                      {!multipleFacesNotice && scanStatus === "SECURE_MATCH" && identifiedUser}
879	                      {!multipleFacesNotice && scanStatus === "UNKNOWN_QUERY" && (identifiedUser || "SUSPICIOUS ACTIVITY")}
880	                    </span>
881	                  </div>
882	                </div>
883	              )}
884	
885	              <div className="hud-overlay">
886	                <div className="hud-top">
887	                  <div className="hud-left-meta">
888	                    <span className="hud-node">SYS_MODE // BIOMETRIC_GANTRY</span>
889	                    {scanStatus === "PRESENCE_DETECTED" && (
890	                      <span className="hud-radar-alert">
891	                        {multipleFacesNotice ? "MULTIPLE FACES DETECTED" : "PROXIMITY SIGNAL DETECTED"}
892	                      </span>
893	                    )}
894	                  </div>
895	                  <span className={`hud-status-badge status-${scanStatus.toLowerCase()}`}>
896	                    {scanStatus === "SYSTEM_ACTIVE" && "IDLE MONITORING"}
897	                    {scanStatus === "PRESENCE_DETECTED" && "MOTION ACQUIRED"}
898	                    {scanStatus === "TARGET_LOCKING" && "VECTOR LOCK ACTIVE"}
899	                    {scanStatus === "LIVENESS_CHECK" && "HEAD-TURN VERIFICATION"}
900	                    {scanStatus === "AUTHORIZING" && "FINAL IDENTITY CHECK"}
901	                    {scanStatus === "SECURE_MATCH" && "SUCCESS MATCH"}
902	                    {scanStatus === "UNKNOWN_QUERY" && "ALERT WARNING"}
903	                  </span>
904	                </div>
905	
906	                <div className="hud-bottom">
907	                  <div className="hud-coordinates-telemetry">
908	                    <p>LAT: 1.3521 N // LON: 103.8198 E</p>
909	                    <p className="hud-engine-log">MATRIX_ENGINE: ACTIVE_v3.42</p>
910	                  </div>
911	                  <p className="hud-clock">{systemTime}</p>
912	                </div>
913	              </div>
914	            </div>
915	          </div>
916	
917	          <div className="vpatrol-card timeline-section">
918	            <div className="section-header">
919	              <h2>Security Timeline</h2>
920	            </div>
921	
922	            {/* Compact filter row - dropdowns + search, frontend filtering only */}
923	            <div className="timeline-filters">
924	              <select
925	                className="timeline-filter"
926	                value={dateFilter}
927	                onChange={(e) => setDateFilter(e.target.value)}
928	                aria-label="Filter by date"
929	              >
930	                {DATE_FILTERS.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
931	              </select>
932	              <select
933	                className="timeline-filter"
934	                value={eventFilter}
935	                onChange={(e) => setEventFilter(e.target.value)}
936	                aria-label="Filter by event type"
937	              >
938	                {EVENT_FILTERS.map(f => <option key={f.value} value={f.value}>{f.label}</option>)}
939	              </select>
940	              <input
941	                type="text"
942	                className="timeline-filter timeline-search"
943	                placeholder="Search name / role / location..."
944	                value={searchFilter}
945	                onChange={(e) => setSearchFilter(e.target.value)}
946	                aria-label="Search timeline"
947	              />
948	              {hasActiveFilters(activeFilters) && (
949	                <button
950	                  type="button"
951	                  className="timeline-clear-btn"
952	                  onClick={() => { setDateFilter('all'); setEventFilter('all'); setSearchFilter(''); }}
953	                >
954	                  Clear Filters
955	                </button>
956	              )}
957	            </div>
958	
959	            <div className="vpatrol-list">
960	              {incidentLogs.length === 0 ? (
961	                <p>Initializing security sensors...</p>
962	              ) : filteredLogs.length === 0 ? (
963	                <div className="timeline-empty">
964	                  <p>No security events match the current filters.</p>
965	                  <button
966	                    type="button"
967	                    className="timeline-clear-btn"
968	                    onClick={() => { setDateFilter('all'); setEventFilter('all'); setSearchFilter(''); }}
969	                  >
970	                    Clear Filters
971	                  </button>
972	                </div>
973	              ) : filteredLogs.map((log) => {
974	                const accessResult = deriveAccessResult(log);
975	                const timestamp = getLogTimestamp(log);
976	                const timeLabel = formatSingaporeTimestamp(timestamp) || log.time || 'Unknown time';
977	                const confidencePct = typeof log.confidence === 'number'
978	                  ? `${Math.round(log.confidence * 100)}%` : null;
979	                return (
980	                  <div key={log.id} className={`vpatrol-item ${log.severity}`}>
981	                    {/* Primary: event, person, outcome */}
982	                    <div className="item-body">
983	                      <div className="item-icon"><SecurityLogIcon log={log} /></div>
984	                      <div className="item-text">
985	                        <div className="item-title-row">
986	                          <h4>{log.type}</h4>
987	                          <span className={`access-result-badge result-${accessResult.toLowerCase()}`}>
988	                            {accessResult}
989	                          </span>
990	                        </div>
991	                        <p className="item-person">
992	                          {log.personnelName || 'Unknown Person'}
993	                          {log.role ? <span className="item-role"> | {log.role}</span> : null}
994	                        </p>
995	                        <p className="item-meta" title={formatSingaporeFull(timestamp) || undefined}>
996	                          {timeLabel}
997	                          {confidencePct ? ` | ${confidencePct} confidence` : ''}
998	                          {log.cameraLocation ? ` | ${log.cameraLocation}` : ''}
999	                        </p>
1000	                        <p className="item-desc">{log.desc}</p>
1001	                      </div>
1002	                    </div>
1003	                    {/* Secondary: muted UUID + review status */}
1004	                    <div className="item-footer-muted">
1005	                      <span className="item-id-muted">#{log.id}</span>
1006	                      {log.reviewStatus ? <span className="item-review-status">{log.reviewStatus}</span> : null}
1007	                    </div>
1008	                  </div>
1009	                );
1010	              })}
1011	            </div>
1012	          </div>
1013	        </div>
1014	      </main>
1015	    </div>
1016	  );
1017	};
1018	
1019	export default VPatrol;
