1	// Frontend tests — Driver Pass renders booking + QR, and degrades cleanly.
2	import React from "react";
3	import { render, screen, waitFor, fireEvent } from "@testing-library/react";
4	import { MemoryRouter, Routes, Route } from "react-router-dom";
5	import { vi, describe, test, expect, afterEach } from "vitest";
6	
7	import DriverPass from "../../src/pages/DriverPass";
8	
9	const renderPass = (ref = "FG-052B13") =>
10	  render(
11	    <MemoryRouter initialEntries={[`/driver-pass/${ref}`]}>
12	      <Routes>
13	        <Route path="/driver-pass/:ref" element={<DriverPass />} />
14	      </Routes>
15	    </MemoryRouter>
16	  );
17	
18	const mockFetchOnce = (impl) => { global.fetch = vi.fn(impl); };
19	
20	afterEach(() => { vi.restoreAllMocks(); delete global.fetch; });
21	
22	describe("DriverPass", () => {
23	  test("renders a valid booking with details and a QR code", async () => {
24	    mockFetchOnce(() => Promise.resolve({
25	      ok: true,
26	      json: () => Promise.resolve({
27	        booking_ref: "FG-052B13", transport_company: "NinjaVan", license_plate: "GBG 1234M",
28	        driver_name: "Ahmad", loading_bay: "Bay A", slot_start: "2026-06-21T09:00",
29	        slot_end: "2026-06-21T10:00", status: "Confirmed",
30	      }),
31	    }));
32	
33	    const { container } = renderPass();
34	    expect(await screen.findByText("FG-052B13")).toBeTruthy();
35	    expect(screen.getByText("NinjaVan")).toBeTruthy();
36	    expect(screen.getByText("GBG 1234M")).toBeTruthy();
37	    expect(screen.getByText("Ahmad")).toBeTruthy();
