1	// Frontend tests — live-camera recognition performance cleanup.
2	// Frontend-only: no AI-model, threshold or liveness-rule changes are covered
3	// here — only capture sizing, request throttling and Pi fallback caching.
4	import fs from "node:fs";
5	import path from "node:path";
6	import { describe, test, expect, vi, beforeEach, afterEach } from "vitest";
7	
8	import {
9	  CAPTURE_MAX_WIDTH,
10	  CAPTURE_JPEG_QUALITY,
11	  SCAN_INTERVAL_MS,
12	  createScanGate,
13	} from "../../src/constants/scanControl";
14	import {
15	  PI_UNAVAILABLE_COOLDOWN_MS,
16	  isPiCameraReachableCached,
17	  markPiUnavailable,
18	  isPiInCooldown,
19	  resetPiAvailabilityCache,
20	} from "../../src/constants/piCamera";
21	
22	const readPage = (name) =>
23	  fs.readFileSync(path.resolve(__dirname, `../../src/pages/${name}`), "utf8");
24	
25	beforeEach(() => {
26	  resetPiAvailabilityCache();
27	});
28	
29	afterEach(() => {
30	  vi.unstubAllGlobals();
31	});
32	
33	describe("frame capture optimisation", () => {
34	  test("frames are resized to a bounded width, not full webcam resolution", () => {
35	    expect(CAPTURE_MAX_WIDTH).toBeLessThanOrEqual(640);
36	    for (const page of ["VPatrol.jsx", "GateScanner.jsx"]) {
37	      const source = readPage(page);
38	      expect(source).toMatch(/CAPTURE_MAX_WIDTH/);
39	      // Both canvas dimensions derive from the scaled-down width.
40	      expect(source).toMatch(/Math\.min\(1,\s*(MAX_WIDTH|maxWidth)\s*\/\s*(bitmap|video)\.(width|videoWidth)\)/);
41	    }
42	  });
43	
44	  test("JPEG quality is reduced (never full quality) and shared by both scanners", () => {
45	    expect(CAPTURE_JPEG_QUALITY).toBeGreaterThanOrEqual(0.55);
46	    expect(CAPTURE_JPEG_QUALITY).toBeLessThanOrEqual(0.7);
47	    for (const page of ["VPatrol.jsx", "GateScanner.jsx"]) {
48	      const source = readPage(page);
49	      // The shared capture helper is parameterized; recognition passes the
50	      // tuned CAPTURE_JPEG_QUALITY constant through it.
51	      expect(source).toMatch(/toDataURL\('image\/jpeg',\s*quality\)/);
52	      expect(source).toMatch(/captureFrom\(canvasRef\.current,\s*CAPTURE_MAX_WIDTH,\s*CAPTURE_JPEG_QUALITY\)/);
53	      // No hardcoded full-quality (or stray) JPEG encodes remain.
54	      expect(source).not.toMatch(/toDataURL\('image\/jpeg',\s*[01]?\.?\d*\)/);
55	      expect(source).not.toMatch(/toDataURL\('image\/jpeg'\)/);
56	    }
57	  });
58	
59	  test("both scanners reuse one hidden canvas ref instead of creating canvases per frame", () => {
60	    for (const page of ["VPatrol.jsx", "GateScanner.jsx"]) {
61	      const source = readPage(page);
62	      expect(source).toMatch(/canvasRef\s*=\s*useRef/);
63	      expect(source).not.toMatch(/document\.createElement\(['"]canvas['"]\)/);
64	    }
65	  });
66	});
67	
68	describe("recognition request throttling", () => {
69	  test("scan gate blocks overlapping recognition requests", () => {
70	    const gate = createScanGate();
71	    gate.begin();
72	    expect(gate.canScan()).toBe(false); // second request cannot start while one is in flight
73	    gate.end();
74	    expect(gate.canScan()).toBe(true);
75	  });
76	
77	  test("operational scans run on a throttled interval, not per video frame", () => {
78	    expect(SCAN_INTERVAL_MS).toBeGreaterThanOrEqual(500);
79	    for (const page of ["VPatrol.jsx", "GateScanner.jsx"]) {
80	      expect(readPage(page)).toMatch(/setInterval\([\s\S]*?,\s*SCAN_INTERVAL_MS\)/);
81	    }
82	  });
83	
84	  test("both scanners guard the loop with the scan gate", () => {
85	    for (const page of ["VPatrol.jsx", "GateScanner.jsx"]) {
86	      const source = readPage(page);
87	      expect(source).toMatch(/createScanGate\(\)/);
88	      expect(source).toMatch(/canScan\(\)/);
89	      expect(source).toMatch(/\.begin\(\)/);
90	      expect(source).toMatch(/\.end\(\)/);
91	    }
92	  });
93	});
94	
95	describe("stale-response protection", () => {
96	  test("responses are dropped after a camera source switch or unmount", () => {
97	    for (const page of ["VPatrol.jsx", "GateScanner.jsx"]) {
98	      const source = readPage(page);
99	      // Session token captured before the request...
100	      expect(source).toMatch(/scanSession(Ref)?\s*=\s*scanSessionRef\.current/);
101	      // ...checked after the response...
102	      expect(source).toMatch(/scanSession !== scanSessionRef\.current\) return/);
103	      // ...and invalidated on source switch and unmount.
