1	// Frontend unit test — shared Singapore-plate normalisation (browser copy).
2	import { describe, test, expect } from "vitest";
3	import { normalizePlate, platesMatch } from "../../src/utils/plate";
4	import { isValidBookingRef, normalizeBookingRef } from "../../src/utils/gateCamera";
5	
6	describe("normalizePlate (client)", () => {
7	  test("collapses spacing/dashes/case to one canonical string", () => {
8	    expect(normalizePlate("GBG 1234 M")).toBe("GBG1234M");
9	    expect(normalizePlate("GBG-1234M")).toBe("GBG1234M");
10	    expect(normalizePlate("gbg1234m")).toBe("GBG1234M");
11	  });
12	  test("is null-safe", () => {
13	    expect(normalizePlate(null)).toBe("");
14	    expect(normalizePlate(undefined)).toBe("");
15	  });
16	  test("platesMatch ignores formatting but not identity", () => {
17	    expect(platesMatch("GBG 1234 M", "gbg-1234m")).toBe(true);
18	    expect(platesMatch("GBG1234M", "GBG1284M")).toBe(false);
19	    expect(platesMatch("", "GBG1234M")).toBe(false);
20	  });
21	});
22	
23	describe("booking-reference validation", () => {
