1	// Browser camera + QR helpers for the Gate Verification page.
2	//
3	// Decoding order (fastest practical path first):
4	//   1. Native browser BarcodeDetector (qr_code) when supported
5	//   2. @zxing/browser BrowserQRCodeReader as the compatibility fallback
6	//   3. Cloud OpenCV snapshot decode after a local timeout (Phase 5, via the
7	//      onCloudDecode callback the page supplies — it POSTs a still to the Node
8	//      /api/qr/decode proxy; this module never calls FastAPI directly)
9	//   4. Manual booking-reference entry (handled by the page)
10	//
11	// We deliberately use BrowserQRCodeReader (NOT BrowserMultiFormatReader) —
12	// FlowGuard only needs QR. @zxing/browser is dynamically imported so it stays
13	// out of the initial bundle, and preloadQrScanner() warms it while the page
14	// loads so pressing "Start Scanner" doesn't wait on a download.
15	//
16	// All camera access is user-initiated and every start returns a stop() that
17	// releases the camera tracks and cancels timers / in-flight cloud requests. QR
18	// frames are never stored — decoding is live-only and captures are in-memory.
19	
20	import {
21	  isSecureCameraContext,
22	  isCameraSupported,
23	  cameraErrorMessage,
24	  mapGetUserMediaError,
25	  startWebcamStream,
26	  stopStream,
27	  QR_WEBCAM_CONSTRAINTS,
28	  logTrackSettings,
29	} from './cameraSource';
30	
31	// Re-export the shared context/support/error helpers so existing imports from
32	// '../utils/gateCamera' keep working unchanged (the pages and tests import
33	// these names from here).
34	export { isSecureCameraContext, isCameraSupported, cameraErrorMessage };
35	
36	// FlowGuard booking references look like "FG-XXXXXX" (genRef → FG + 6 hex chars).
37	// Accept FG- followed by 4–12 alphanumerics; reject arbitrary QR text.
38	const BOOKING_REF_RE = /^FG-[A-Z0-9]{4,12}$/;
39	
40	export function normalizeBookingRef(raw) {
41	  return String(raw ?? '').trim().toUpperCase();
42	}
43	
44	export function isValidBookingRef(raw) {
45	  return BOOKING_REF_RE.test(normalizeBookingRef(raw));
46	}
47	
48	// User-facing scanner states (the page maps these to inline status copy).
49	export const SCANNER_STATE = Object.freeze({
50	  LOADING: 'loading-scanner',          // Loading scanner…
51	  STARTING: 'starting-camera',         // Starting camera…
52	  CAMERA_READY: 'camera-ready',        // Camera ready
53	  LOOKING: 'looking',                  // Looking for QR…
54	  QR_DETECTED: 'qr-detected',          // QR detected
55	  VERIFYING: 'verifying',              // Verifying booking…
56	  VERIFIED: 'verified',                // Booking verified
57	  DENIED: 'denied',                    // Booking denied
58	  SLOW: 'local-slow',                  // Local scan taking longer than expected
59	  CLOUD: 'cloud-trying',               // Trying cloud-assisted scan…
60	  MANUAL: 'manual-available',          // Manual entry available
61	  PERMISSION_DENIED: 'permission-denied', // Camera permission denied
62	  UNAVAILABLE: 'camera-unavailable',   // Camera unavailable
63	});
64	
65	// Which decoder produced a result (for timing metrics / diagnostics).
66	export const DECODER_SOURCE = Object.freeze({
67	  BARCODE_DETECTOR: 'barcode-detector-browser',
68	  ZXING: 'zxing-browser',
69	  OPENCV_CLOUD: 'opencv-cloud',
70	  PI_CAMERA_CLOUD: 'pi-camera-cloud',
71	  MANUAL: 'manual-entry',
72	});
73	
74	// How long the local scanner runs before the cloud snapshot fallback activates.
75	export const DEFAULT_CLOUD_FALLBACK_DELAY_MS = 2500;
76	// Never upload more than ~1 cloud snapshot per second.
77	export const CLOUD_SNAPSHOT_MIN_INTERVAL_MS = 1000;
78	// Local BarcodeDetector cadence (one detect in flight at a time).
79	const BARCODE_SCAN_INTERVAL_MS = 120;
80	
81	// True when the native BarcodeDetector API can decode QR codes in this browser.
82	export function isBarcodeDetectorSupported() {
83	  return typeof window !== 'undefined' && 'BarcodeDetector' in window;
84	}
85	
86	// Module-level cache so the zxing reader is created ONCE and reused across
87	// starts (never recreated on every render). Also caches the last camera
88	// deviceId so re-starts reuse the same camera without re-prompting.
89	let zxingModulePromise = null;
90	let barcodeDetectorSupported = null;
91	let lastDeviceId = null;
92	
93	/**
94	 * Warm the QR scanner while the page loads: probe BarcodeDetector support and
95	 * begin downloading @zxing/browser so the first "Start Scanner" is instant.
96	 * Safe to call multiple times — the import promise is cached. Never throws.
97	 */
98	export function preloadQrScanner() {
99	  if (barcodeDetectorSupported === null) {
100	    barcodeDetectorSupported = isBarcodeDetectorSupported();
101	  }
102	  // Only bother downloading zxing if we might actually need the fallback.
103	  if (!zxingModulePromise) {
104	    zxingModulePromise = import('@zxing/browser').catch((e) => {
105	      zxingModulePromise = null; // allow a later retry
106	      throw e;
107	    });
108	  }
109	  // Swallow rejection here so an eager preload never surfaces an unhandled
110	  // rejection; startQrScan re-imports (cached) and handles errors there.
111	  return zxingModulePromise.then(() => true).catch(() => false);
112	}
113	
114	function getZxingModule() {
115	  if (!zxingModulePromise) {
116	    zxingModulePromise = import('@zxing/browser');
117	  }
118	  return zxingModulePromise;
119	}
120	
121	/**
122	 * Draw the current video frame to an offscreen canvas and return a compressed
123	 * JPEG data URL — the still uploaded to the cloud decoder. Bounded width keeps
124	 * the payload small while preserving enough detail for QR decoding. In-memory
125	 * only; the canvas is discarded when this returns.
126	 */
127	export function captureVideoFrameJpeg(videoElement, { maxWidth = 1024, quality = 0.85 } = {}) {
128	  if (!videoElement || !videoElement.videoWidth) return null;
129	  const scale = Math.min(1, maxWidth / videoElement.videoWidth);
130	  const canvas = document.createElement('canvas');
131	  canvas.width = Math.round(videoElement.videoWidth * scale);
132	  canvas.height = Math.round(videoElement.videoHeight * scale);
133	  const ctx = canvas.getContext('2d');
134	  ctx.drawImage(videoElement, 0, 0, canvas.width, canvas.height);
135	  return canvas.toDataURL('image/jpeg', quality);
136	}
137	
138	// Dev-only QR timing telemetry: durations + decoder source ONLY — never image
139	// data. No-op in production builds.
140	export function logQrTimings(metrics) {
141	  if (!import.meta.env?.DEV) return;
142	  const parts = [
143	    metrics.cameraStartupMs != null ? `camera-start ${metrics.cameraStartupMs}ms` : null,
144	    metrics.firstFrameMs != null ? `first-frame ${metrics.firstFrameMs}ms` : null,
145	    metrics.localDecodeMs != null ? `local-decode ${metrics.localDecodeMs}ms` : null,
146	    metrics.cloudDecodeMs != null ? `cloud-decode ${metrics.cloudDecodeMs}ms` : null,
147	    metrics.decoder ? `via ${metrics.decoder}` : null,
148	  ].filter(Boolean);
149	  if (parts.length) console.debug(`[qr timing] ${parts.join(' | ')}`);
150	}
151	
152	// Start a plain live-preview camera (used by the PoC plate-capture step).
153	// Throws a coded Error (code: insecure | unsupported | permission | no-camera |
154	// unknown). Returns { stop } to release the camera.
155	export async function startCamera(videoElement) {
156	  const { stop } = await startWebcamStream(videoElement, QR_WEBCAM_CONSTRAINTS);
157	  return { stop };
158	}
159	
160	/**
161	 * Start live QR decoding on a <video>.
162	 *
163	 * @param {object}   opts
164	 * @param {HTMLVideoElement} opts.videoElement
